head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > ref]<br/>Multiselect 컴포넌트의 선택값에 바인딩할 DataCollection 정보를 설정합니다.",
    "validation" : [
        "접근 가능한 DataCollection 의 컬럼을 'data:[DataCollection ID].[Key 또는 Column ID]' 형식으로 설정합니다.",
        "유효하지 않은 값으로 설정 시 바인딩 처리되지 않고 아이템 선택이 연동되지 않습니다.",
        "컴포넌트에서 선택한 아이템의 Value 값이 바인딩 된 DataCollection 에 반영됩니다.",
        "아이템을 한 개 이상 선택 시 separator 속성값을 구분자로 아이템의 Value 값이 DataCollection 에 반영됩니다.",
        "DataList 를 바인딩 했을때 DataList 에 선택한 데이터가 없으면 DataList 에 선택된 아이템 Value 가 반영되지 않습니다.",
        "아이템을 선택하거나 setValue(), setSelectedIndex() 메소드로 선택값을 변경하면 DataCollection 에 반영되고 onchange 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 (gdl_multiselect 포함)
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// onchange 이벤트 핸들러 — multiselect onchange 는 파라미터 없음 (engine spec)
// 변경된 값은 getValue() / getSelectedIndex() 메소드로 직접 조회
scwin.target1_onchange = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : " + target1.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : " + target1.getSelectedIndex());
};



// 바인딩된 dlt_ref 의 현재 row 값 확인
scwin.btn_getDataList_onclick = function (e) {
    let rsData = dlt_ref.getAllJSON();
    for (let i = 0; i < rsData.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + i + " value : " + rsData[i].value);
    }
};



// setValue: 입력값을 multiselect 에 설정 → ref 바인딩 통해 dlt_ref 반영 확인
scwin.btn_setValue_onclick = function (e) {
    let v = par_value.getValue();
    target1.setValue(v);
    wf_body_bottom.getObj("scwin").setReturnValue("setValue('" + v + "') 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : " + target1.getValue());
};



// setSelectedIndex: 인덱스로 선택 → ref 바인딩 통해 dlt_ref 반영 확인
scwin.btn_setSelectedIndex_onclick = function (e) {
    let idx = par_index.getValue();
    target1.setSelectedIndex(idx);
    wf_body_bottom.getObj("scwin").setReturnValue("setSelectedIndex('" + idx + "') 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : " + target1.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : " + target1.getSelectedIndex());
};
